# Plan-only coverage for the gateway request and token autoscaling policies.
# Offline via mock_provider, same as byo_infrastructure.tftest.hcl.

mock_provider "aws" {
  mock_data "aws_iam_policy_document" {
    defaults = {
      json = "{\"Version\":\"2012-10-17\",\"Statement\":[]}"
    }
  }
}
mock_provider "random" {}

variables {
  region              = "us-east-1"
  tenant              = "acme"
  env                 = "test"
  allow_plaintext_alb = true
  azs                 = ["us-east-1a", "us-east-1b"]
}

run "defaults_scale_on_cpu_and_memory_only" {
  command = plan

  assert {
    condition = alltrue([
      length(aws_appautoscaling_policy.gateway_cpu) == 1,
      length(aws_appautoscaling_policy.gateway_memory) == 1,
      length(aws_appautoscaling_policy.gateway_requests) == 0,
      length(aws_appautoscaling_policy.gateway_tokens) == 0,
    ])
    error_message = "Request and token policies must be absent by default while the CPU and memory policies stay."
  }
}

run "requests_per_second_adds_an_alb_request_count_policy" {
  command = plan

  variables {
    gateway_target_requests_per_second = 90
  }

  assert {
    condition     = length(aws_appautoscaling_policy.gateway_requests) == 1 && length(aws_appautoscaling_policy.gateway_tokens) == 0
    error_message = "A request target alone must add exactly the request policy."
  }

  assert {
    condition = alltrue([
      aws_appautoscaling_policy.gateway_requests[0].name == "acme-litellm-test-gateway-requests",
      aws_appautoscaling_policy.gateway_requests[0].policy_type == "TargetTrackingScaling",
      aws_appautoscaling_policy.gateway_requests[0].service_namespace == "ecs",
      aws_appautoscaling_policy.gateway_requests[0].resource_id == "service/acme-litellm-test/acme-litellm-test-gateway",
      aws_appautoscaling_policy.gateway_requests[0].scalable_dimension == "ecs:service:DesiredCount",
    ])
    error_message = "The request policy must be a target-tracking policy on the gateway service's desired count."
  }

  assert {
    condition = alltrue([
      one(aws_appautoscaling_policy.gateway_requests[0].target_tracking_scaling_policy_configuration).target_value == 5400,
      one(one(aws_appautoscaling_policy.gateway_requests[0].target_tracking_scaling_policy_configuration).predefined_metric_specification).predefined_metric_type == "ALBRequestCountPerTarget",
      length(one(aws_appautoscaling_policy.gateway_requests[0].target_tracking_scaling_policy_configuration).customized_metric_specification) == 0,
    ])
    error_message = "The request policy must track ALBRequestCountPerTarget at 60 times the configured requests per second per task."
  }
}

run "tokens_per_second_adds_a_metric_math_policy" {
  command = plan

  variables {
    gateway_target_tokens_per_second = 6000000
    gateway_tokens_metric = {
      namespace  = "LiteLLM/Prometheus"
      dimensions = { ClusterName = "acme-litellm-test", TaskDefinitionFamily = "acme-litellm-test-gateway" }
    }
  }

  assert {
    condition     = length(aws_appautoscaling_policy.gateway_tokens) == 1 && length(aws_appautoscaling_policy.gateway_requests) == 0
    error_message = "A token target alone must add exactly the token policy."
  }

  assert {
    condition = alltrue([
      aws_appautoscaling_policy.gateway_tokens[0].name == "acme-litellm-test-gateway-tokens",
      aws_appautoscaling_policy.gateway_tokens[0].resource_id == "service/acme-litellm-test/acme-litellm-test-gateway",
      one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).target_value == 6000000,
      length(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).predefined_metric_specification) == 0,
    ])
    error_message = "The token policy must track a customized metric at the configured tokens per second per task."
  }

  assert {
    condition = alltrue([
      length(one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics) == 4,
      { for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["tokens"].id == "tokens",
      { for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["tokens"].return_data == false,
      one({ for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["tokens"].metric_stat).stat == "Sum",
      one(one({ for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["tokens"].metric_stat).metric).namespace == "LiteLLM/Prometheus",
      one(one({ for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["tokens"].metric_stat).metric).metric_name == "litellm_total_tokens_metric_total",
      { for d in one(one({ for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["tokens"].metric_stat).metric).dimensions : d.name => d.value } == { ClusterName = "acme-litellm-test", TaskDefinitionFamily = "acme-litellm-test-gateway" },
    ])
    error_message = "The first metric must sum the published token counter deltas under the configured namespace and dimensions."
  }

  assert {
    condition = alltrue([
      { for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["running_tasks"].id == "running_tasks",
      { for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["running_tasks"].return_data == false,
      one({ for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["running_tasks"].metric_stat).stat == "Average",
      one(one({ for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["running_tasks"].metric_stat).metric).namespace == "ECS/ContainerInsights",
      one(one({ for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["running_tasks"].metric_stat).metric).metric_name == "RunningTaskCount",
      { for d in one(one({ for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["running_tasks"].metric_stat).metric).dimensions : d.name => d.value } == { ClusterName = "acme-litellm-test", ServiceName = "acme-litellm-test-gateway" },
    ])
    error_message = "The second metric must read the gateway service's Container Insights RunningTaskCount."
  }

  assert {
    condition = alltrue([
      { for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["tokens_per_second"].expression == "tokens / 60",
      { for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["tokens_per_second"].return_data == false,
    ])
    error_message = "The 60s period Sum must be divided by 60 to yield tokens per second."
  }

  assert {
    condition = alltrue([
      { for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["tokens_per_second_per_task"].expression == "tokens_per_second / running_tasks",
      { for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["tokens_per_second_per_task"].return_data == true,
      length([for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m if m.return_data]) == 1,
    ])
    error_message = "Only the per-task tokens per second may return data to the scaling policy."
  }
}

run "tokens_per_second_needs_the_metric_location" {
  command = plan

  variables {
    gateway_target_tokens_per_second = 6000000
  }

  expect_failures = [
    aws_appautoscaling_policy.gateway_tokens,
  ]
}

run "requests_and_tokens_scale_next_to_cpu_and_memory" {
  command = plan

  variables {
    gateway_target_requests_per_second = 90
    gateway_target_tokens_per_second   = 6000000
    gateway_tokens_metric              = { namespace = "LiteLLM/Prometheus" }
  }

  assert {
    condition = alltrue([
      length(aws_appautoscaling_policy.gateway_cpu) == 1,
      length(aws_appautoscaling_policy.gateway_memory) == 1,
      length(aws_appautoscaling_policy.gateway_requests) == 1,
      length(aws_appautoscaling_policy.gateway_tokens) == 1,
      one(aws_appautoscaling_policy.gateway_cpu[0].target_tracking_scaling_policy_configuration).target_value == 70,
      one(aws_appautoscaling_policy.gateway_memory[0].target_tracking_scaling_policy_configuration).target_value == 80,
    ])
    error_message = "Workload policies must coexist with the CPU and memory policies at their default targets."
  }

  assert {
    condition     = length(one(one({ for m in one(one(aws_appautoscaling_policy.gateway_tokens[0].target_tracking_scaling_policy_configuration).customized_metric_specification).metrics : m.id => m }["tokens"].metric_stat).metric).dimensions) == 0
    error_message = "Omitting dimensions must query the token metric without any."
  }
}

run "workload_targets_are_ignored_when_autoscaling_is_off" {
  command = plan

  variables {
    gateway_autoscaling_enabled        = false
    gateway_target_requests_per_second = 90
    gateway_target_tokens_per_second   = 6000000
    gateway_tokens_metric              = { namespace = "LiteLLM/Prometheus" }
  }

  assert {
    condition = alltrue([
      length(aws_appautoscaling_target.gateway) == 0,
      length(aws_appautoscaling_policy.gateway_requests) == 0,
      length(aws_appautoscaling_policy.gateway_tokens) == 0,
    ])
    error_message = "Disabling gateway autoscaling must drop the workload policies with the target."
  }
}

# Plan-only coverage for the Prometheus metrics sidecar wiring. Offline via
# mock_provider, same as byo_infrastructure.tftest.hcl.

mock_provider "aws" {
  mock_data "aws_iam_policy_document" {
    defaults = {
      json = "{\"Version\":\"2012-10-17\",\"Statement\":[]}"
    }
  }
}
mock_provider "random" {}

variables {
  region              = "us-east-1"
  tenant              = "acme"
  env                 = "test"
  allow_plaintext_alb = true
  azs                 = ["us-east-1a", "us-east-1b"]
}

run "defaults_change_nothing" {
  command = plan

  assert {
    condition = alltrue([
      length(local.gateway_metrics_container) == 0,
      length(local.metrics_env) == 0,
      length(local.metrics_mount_points) == 0,
      length([for r in aws_security_group.tasks.ingress : r if r.description == "Prometheus scrapers to the gateway metrics sidecar"]) == 0,
    ])
    error_message = "The metrics sidecar, its env, its volume, and its security-group rule must all be absent by default."
  }
}

run "metrics_port_adds_a_sidecar_volume_and_scrape_rule" {
  command = plan

  variables {
    gateway_metrics_port         = 9464
    gateway_metrics_scrape_cidrs = ["10.20.0.0/16"]
  }

  assert {
    condition     = length(local.metrics_env) == 1 && local.metrics_env[0].name == "PROMETHEUS_MULTIPROC_DIR" && local.metrics_env[0].value == "/tmp/litellm_prometheus_multiproc"
    error_message = "The gateway workers must write multiprocess samples to the shared dir."
  }

  assert {
    condition     = length(local.metrics_mount_points) == 1 && local.metrics_mount_points[0].sourceVolume == "prometheus-multiproc" && local.metrics_mount_points[0].containerPath == "/tmp/litellm_prometheus_multiproc"
    error_message = "Gateway and sidecar must mount the same task volume at the multiproc dir."
  }

  assert {
    condition = alltrue([
      length(local.gateway_metrics_container) == 1,
      local.gateway_metrics_container[0].name == "metrics",
      local.gateway_metrics_container[0].essential == false,
      join(" ", local.gateway_metrics_container[0].entryPoint) == "python -m litellm.proxy.prometheus_metrics_server",
      join(" ", local.gateway_metrics_container[0].command) == "--port 9464",
      one(local.gateway_metrics_container[0].portMappings).containerPort == 9464,
      one(local.gateway_metrics_container[0].environment).value == "/tmp/litellm_prometheus_multiproc",
      one(local.gateway_metrics_container[0].mountPoints).sourceVolume == "prometheus-multiproc",
      strcontains(local.gateway_metrics_container[0].healthCheck.command[3], "9464"),
    ])
    error_message = "The metrics sidecar must run prometheus_metrics_server on the configured port, share the multiproc volume, and health-check that port."
  }

  assert {
    condition     = length(aws_ecs_task_definition.gateway.volume) == 1 && one(aws_ecs_task_definition.gateway.volume).name == "prometheus-multiproc"
    error_message = "The gateway task must declare the multiproc volume."
  }

  assert {
    condition = length([
      for r in aws_security_group.tasks.ingress : r
      if r.from_port == 9464 && r.to_port == 9464 && r.protocol == "tcp" && r.cidr_blocks == tolist(["10.20.0.0/16"])
    ]) == 1
    error_message = "The scrape CIDRs must be allowed to reach the metrics port on the tasks security group."
  }

  assert {
    condition     = aws_lb_target_group.gateway.port == 4000 && one(aws_ecs_service.gateway.load_balancer).container_port == 4000
    error_message = "The ALB must keep targeting the gateway port only; the metrics port is never load balanced."
  }
}

run "metrics_port_without_scrape_cidrs_opens_nothing" {
  command = plan

  variables {
    gateway_metrics_port = 9464
  }

  assert {
    condition     = length(local.gateway_metrics_container) == 1 && length([for r in aws_security_group.tasks.ingress : r if r.from_port == 9464]) == 0
    error_message = "Without scrape CIDRs the sidecar runs but the metrics port stays closed to everything but the ALB group."
  }
}

run "metrics_port_may_not_reuse_the_gateway_port" {
  command = plan

  variables {
    gateway_metrics_port = 4000
  }

  expect_failures = [var.gateway_metrics_port]
}

# Plan-only coverage for the in-container PgBouncer knobs on the gateway task.
# `mock_provider` keeps this offline: no AWS credentials, no API calls, no
# resources. Run from terraform/litellm/aws with `terraform test`.

mock_provider "aws" {
  mock_data "aws_iam_policy_document" {
    defaults = {
      json = "{\"Version\":\"2012-10-17\",\"Statement\":[]}"
    }
  }
}
mock_provider "random" {}

variables {
  region              = "us-east-1"
  tenant              = "acme"
  env                 = "test"
  azs                 = ["us-east-1a", "us-east-1b"]
  allow_plaintext_alb = true
}

run "pool_off_by_default" {
  command = plan

  assert {
    condition     = length(local.gateway_pool_env) == 0
    error_message = "The gateway must get no LITELLM_PGBOUNCER_* env unless gateway_connection_pool_enabled is set."
  }
}

run "pool_enabled_renders_the_three_vars_with_configured_sizes" {
  command = plan

  variables {
    create_database                 = false
    database_url                    = "postgresql://litellm:pw@db.internal:5432/litellm"
    gateway_num_workers             = 4
    gateway_connection_pool_enabled = true
    gateway_pool_max_db_connections = 8
    gateway_pool_max_client_conn    = 250
  }

  assert {
    condition = alltrue([
      length(local.gateway_pool_env) == 3,
      local.gateway_pool_env[0].name == "LITELLM_PGBOUNCER_ENABLED" && local.gateway_pool_env[0].value == "true",
      local.gateway_pool_env[1].name == "LITELLM_PGBOUNCER_MAX_DB_CONNECTIONS" && local.gateway_pool_env[1].value == "8",
      local.gateway_pool_env[2].name == "LITELLM_PGBOUNCER_MAX_CLIENT_CONN" && local.gateway_pool_env[2].value == "250",
    ])
    error_message = "The pool env must carry the enabled flag and the configured sizes as strings."
  }
}

run "collector_sidecar_gets_the_same_pool_env_as_the_gateway" {
  command = plan

  variables {
    create_database                 = false
    database_url                    = "postgresql://litellm:pw@db.internal:5432/litellm"
    collector_enabled               = true
    gateway_connection_pool_enabled = true
    gateway_pool_max_db_connections = 8
    gateway_pool_max_client_conn    = 250
  }

  assert {
    condition = alltrue([
      for env in [local.gateway_environment, local.collector_container[0].environment] : (
        { for e in env : e.name => e.value }["LITELLM_PGBOUNCER_ENABLED"] == "true" &&
        { for e in env : e.name => e.value }["LITELLM_PGBOUNCER_MAX_DB_CONNECTIONS"] == "8" &&
        { for e in env : e.name => e.value }["LITELLM_PGBOUNCER_MAX_CLIENT_CONN"] == "250"
      )
    ])
    error_message = "The collector sidecar must carry the same three LITELLM_PGBOUNCER_* vars as the gateway so its Prisma connects to the task-local pool."
  }
}

run "collector_sidecar_gets_no_pool_env_when_the_pool_is_off" {
  command = plan

  variables {
    collector_enabled = true
  }

  assert {
    condition     = !anytrue([for e in local.collector_container[0].environment : startswith(e.name, "LITELLM_PGBOUNCER_")])
    error_message = "The collector sidecar must get no LITELLM_PGBOUNCER_* env unless gateway_connection_pool_enabled is set."
  }
}

run "pool_enabled_uses_the_module_default_sizes" {
  command = plan

  variables {
    create_database                 = false
    database_url                    = "postgresql://litellm:pw@db.internal:5432/litellm"
    gateway_connection_pool_enabled = true
  }

  assert {
    condition = alltrue([
      length(local.gateway_pool_env) == 3,
      local.gateway_pool_env[1].name == "LITELLM_PGBOUNCER_MAX_DB_CONNECTIONS" && local.gateway_pool_env[1].value == "20",
      local.gateway_pool_env[2].name == "LITELLM_PGBOUNCER_MAX_CLIENT_CONN" && local.gateway_pool_env[2].value == "1000",
    ])
    error_message = "The pool env must fall back to the module defaults of 20 upstream and 1000 client connections."
  }
}

run "gateway_starts_through_the_pool_aware_launcher" {
  command = plan

  variables {
    gateway_num_workers = 4
  }

  assert {
    condition = alltrue([
      strcontains(local.gateway_launch_cmd, "exec python -m gateway.launch --host 0.0.0.0 --port 4000 --workers 4"),
      strcontains(local.gateway_launch_cmd, "exec ddtrace-run python -m gateway.launch --host 0.0.0.0 --port 4000 --workers 4"),
      !strcontains(local.gateway_launch_cmd, "uvicorn gateway.main:app"),
      local.gateway_proxy_overrides.command[0] == local.gateway_launch_cmd,
    ])
    error_message = "The gateway must start through gateway.launch (with and without ddtrace) so the pooler starts once before uvicorn forks the workers."
  }
}

run "pool_with_module_created_iam_aurora_plans_with_both_the_pool_and_iam_auth" {
  command = plan

  variables {
    gateway_connection_pool_enabled = true
  }

  assert {
    condition = alltrue([
      length(local.gateway_pool_env) == 3,
      contains(local.managed_db_env, { name = "IAM_TOKEN_DB_AUTH", value = "true" }),
    ])
    error_message = "With the module-created Aurora the gateway must get the pool env alongside IAM token auth."
  }
}

run "pool_without_any_database_fails_at_plan" {
  command = plan

  variables {
    create_database                 = false
    gateway_connection_pool_enabled = true
  }

  expect_failures = [
    aws_ecs_task_definition.gateway,
  ]
}

run "module_created_iam_aurora_without_the_pool_still_plans" {
  command = plan

  assert {
    condition     = contains(local.managed_db_env, { name = "IAM_TOKEN_DB_AUTH", value = "true" })
    error_message = "Without the pool the module-created Aurora must keep IAM token auth."
  }
}

# Plan-only coverage for the four networking/database/cache permutations.
# `mock_provider` keeps this offline: no AWS credentials, no API calls, no
# resources. Run from terraform/litellm/aws with `terraform test`.

mock_provider "aws" {
  # IAM policy documents are validated as JSON by the provider, so the
  # generated placeholder string has to be replaced with a parsable one.
  mock_data "aws_iam_policy_document" {
    defaults = {
      json = "{\"Version\":\"2012-10-17\",\"Statement\":[]}"
    }
  }
}
mock_provider "random" {}

variables {
  region              = "us-east-1"
  tenant              = "acme"
  env                 = "test"
  allow_plaintext_alb = true
}

run "module_owns_everything_by_default" {
  command = plan

  variables {
    azs = ["us-east-1a", "us-east-1b"]
  }

  assert {
    condition     = length(aws_vpc.this) == 1 && length(aws_nat_gateway.this) == 1 && length(aws_subnet.private) == 2
    error_message = "The default path must still create its own VPC, NAT gateway, and one private subnet per AZ."
  }

  assert {
    condition     = length(aws_rds_cluster.this) == 1 && length(aws_elasticache_replication_group.this) == 1
    error_message = "The default path must still create Aurora and ElastiCache."
  }

  assert {
    condition     = length(aws_secretsmanager_secret.database_url) == 0 && length(aws_secretsmanager_secret.redis_url) == 0
    error_message = "Connection-string secrets belong to the bring-your-own path only."
  }

  assert {
    condition     = length(local.managed_db_env) == 7 && length(local.managed_redis_env) == 3
    error_message = "Gateway, backend, and migration tasks must keep the discrete DATABASE_*/REDIS_* env for the module-created stores."
  }

  assert {
    condition     = length(terraform_data.bootstrap_db) == 1 && length(aws_ecs_task_definition.migrations) == 1
    error_message = "The IAM-user bootstrap and the schema migration must both run against the module-created Aurora."
  }
}

run "existing_vpc_creates_no_networking" {
  command = plan

  variables {
    vpc_id                             = "vpc-00000000000000001"
    public_subnet_ids                  = ["subnet-pub-a", "subnet-pub-b"]
    private_subnet_ids                 = ["subnet-priv-a", "subnet-priv-b"]
    additional_task_security_group_ids = ["sg-caller-owned"]
  }

  assert {
    condition = alltrue([
      length(aws_vpc.this) == 0,
      length(aws_subnet.public) == 0,
      length(aws_subnet.private) == 0,
      length(aws_internet_gateway.this) == 0,
      length(aws_nat_gateway.this) == 0,
      length(aws_eip.nat) == 0,
      length(aws_route_table.public) == 0,
      length(aws_route_table.private) == 0,
    ])
    error_message = "An existing vpc_id must suppress every network resource, including the route tables and NAT gateway."
  }

  assert {
    condition     = aws_lb.this.subnets == toset(var.public_subnet_ids)
    error_message = "The ALB must land in the caller's public subnets."
  }

  assert {
    condition = alltrue([
      aws_db_subnet_group.this[0].subnet_ids == toset(var.private_subnet_ids),
      aws_elasticache_subnet_group.this[0].subnet_ids == toset(var.private_subnet_ids),
      aws_ecs_service.gateway.network_configuration[0].subnets == toset(var.private_subnet_ids),
    ])
    error_message = "Tasks, Aurora, and ElastiCache must land in the caller's private subnets."
  }

  assert {
    condition     = length(local.task_security_group_ids) == 2
    error_message = "additional_task_security_group_ids must be attached alongside the module's own tasks group."
  }
}

run "existing_database_and_redis_replace_the_managed_ones" {
  command = plan

  variables {
